#!/usr/bin/env bash
# Doc dev à jour, 2/2 — chapitre « Majorité, statut et cours » (26.5).
# - Une date qui décide, des groupes qui rendent majeur, devenir majeur (18 ans, pièce d'identité), le tri des
#   comptes d'avant, les cours (indice de minorité, cours suivis, cours donnés) ;
# - renumérotation de la partie « Membres et collaboration », liens et sommaire ;
# - user.markAdults efface aussi le téléphone du parent. Pas de migration.
# Prérequis : apply-doc-a-jour-1.sh.
# Usage (racine du repo) : bash apply-doc-a-jour-2.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/membres/majorite-statut-et-cours.mdx" 2>/dev/null | grep -qF "Majorité, statut et cours"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "Les groupes système : Instructeurs et Bureau" "apps/web/content/docs/dev/membres/les-groupes.mdx" 2>/dev/null || { echo "lancez d'abord apply-doc-a-jour-1.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/index.mdx" "apps/web/content/docs/dev/membres/demandes.mdx" "apps/web/content/docs/dev/membres/espaces-collaboratifs.mdx" "apps/web/content/docs/dev/membres/les-groupes.mdx" "apps/web/src/features/docs/entities/procedureMap.generated.json" "packages/backend/src/modules/users/router.ts")
CREATED=("apps/web/content/docs/dev/membres/majorite-statut-et-cours.mdx")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "Majorité, statut et cours" "apps/web/content/docs/dev/membres/majorite-statut-et-cours.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

mkdir -p "apps/web/content/docs/dev/membres"
